/* Local interactive design experiment. No access to the production storage key. */
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
(function () {
  'use strict';
  const E = MoneyV3, KEY = 'money-prototype-v3';
  const $ = id => document.getElementById(id);
  const today = () => { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); };
  let store = E.seed(false, today()), p, storageWarning = '';
  try { const raw = localStorage.getItem(KEY); if (raw) { const parsed=JSON.parse(raw); if (parsed.schemaVersion === 1 && parsed.base && Array.isArray(parsed.events)) { E.project(parsed); store=parsed; } } } catch (_) { storageWarning='Збереження недоступне або демо пошкоджено. Можна продовжити в цій вкладці.'; }
  let route = 'home', params = {}, toast = '', period = 12, overlay = null;
  let quick = { mode: 'expense', detail: false }, lastTab = 'home';
  const symbols = {USD:'$',EUR:'€',UAH:'₴',GBP:'£'};
  const names = {cash:'Готівка',bank:'Банківський рахунок',dep:'Депозит',biz:'Бізнес',other:'Інше'};
  const types = ['cash','bank','dep','biz','other'];
  const currencies = Object.keys(store.rates);
  const money = (n,c) => (n/100).toLocaleString('uk-UA',{maximumFractionDigits:2}) + ' ' + (symbols[c] || c);
  const shown = n => money(Math.round(n/store.rates[store.currency]),store.currency);
  const val = id => $(id) ? $(id).value : '';
  const amount = value => { const text=String(value).trim().replace(/\s/g,'').replace(',','.'); if (!/^\d+(\.\d{0,2})?$/.test(text)) throw new Error('Введіть суму цифрами, наприклад 1500 або 1500,50.'); const n=Math.round(Number(text)*100); if (!Number.isSafeInteger(n) || n > 1e13) throw new Error('Сума завелика для прототипу.'); return n; };
  const dateLabel = d => new Date(d+'T12:00:00').toLocaleDateString('uk-UA',{day:'numeric',month:'short',year:'numeric'});
  const monthLabel = d => new Date(d.slice(0,7)+'-01T12:00:00').toLocaleDateString('uk-UA',{month:'long',year:'numeric'});
  const aBy = id => p.accounts.find(a=>a.id===id);
  const gBy = id => p.goals.find(g=>g.id===id);
  const options = (list, current, label) => list.map(x=>'<option value="'+esc(typeof x==='string'?x:x.id)+'" '+((typeof x==='string'?x:x.id)===current?'selected':'')+'>'+esc(label?label(x):x)+'</option>').join('');
  const field = (id,label,value,kind='text',extra='') => '<div class="fld"><label for="'+id+'">'+label+'</label><input class="inp" id="'+id+'" name="'+id+'" type="'+kind+'" value="'+esc(value)+'" '+extra+'></div>';
  const select = (id,label,html) => '<div class="fld"><label for="'+id+'">'+label+'</label><select class="inp" id="'+id+'" name="'+id+'">'+html+'</select></div>';
  const toggle = (id,label,on,sub='') => '<label class="toggle-label" for="'+id+'"><span>'+label+(sub?'<small>'+sub+'</small>':'')+'</span><input class="switch" type="checkbox" id="'+id+'" name="'+id+'" '+(on?'checked':'')+'></label>';
  const button = (label,action,id='',cls='second',extra='') => '<button type="button" class="'+cls+'" data-action="'+action+'" data-id="'+esc(id)+'" '+extra+'>'+label+'</button>';
  const row = (title, sub, right, action, id) => '<button type="button" class="row" data-action="'+action+'" data-id="'+esc(id)+'"><span class="l"><span>'+title+(sub?'<small>'+sub+'</small>':'')+'</span></span><span class="r">'+right+'</span></button>';
  const form = (action,html,submit='Зберегти') => '<form class="form" data-form="'+action+'">'+html+'<div class="error" id="form-error" role="alert"></div><button class="primary" type="submit">'+submit+'</button></form>';
  function persist(next) { E.project(next); store=next; try { localStorage.setItem(KEY,JSON.stringify(store)); storageWarning=''; } catch (_) { storageWarning='Не вдалося зберегти демо. Зміни доступні лише до закриття вкладки.'; } }
  function commit(event,msg) { persist(E.append(store,event)); toast=msg||'Збережено'; }
  function go(next, data={}) { route=next; params=data; toast=''; if (['home','accounts','goals','forecast','more'].includes(next)) lastTab=next; render(); $('view').scrollTop=0; }
  function header(title, back) { return '<div class="head">'+(back?button(ic('left'),'go',back,'back','aria-label="Назад"'):'')+'<h1 tabindex="-1">'+title+'</h1></div>'; }
  function curCtl() { return '<select class="currency-select" id="show-currency" aria-label="Валюта підсумку">'+options(currencies,store.currency,c=>symbols[c]+' '+c)+'</select>'; }
  function summary() {
    const total=E.total(p,store.rates), saved=E.pool(p,store.rates), free=total-saved;
    return '<div class="hero-row"><span class="lbl">Усього грошей</span>'+curCtl()+'</div><div class="hero-v3"><div class="ring-v3" style="--portion:'+Math.min(100,total?saved/total*100:0)+'%"><span>'+ic('tabAcc',26)+'<span>Ваші кошти</span></span></div><div style="min-width:0"><div class="total">'+shown(total)+'</div><div class="sub">На всіх рахунках</div></div></div>'+(p.goals.some(E.live)?'<div class="card two"><div><div class="pl-n">Вільні</div><div class="big-a '+(free<0?'negative':'')+'">'+shown(free)+'</div></div><div><div class="pl-n">На цілі</div><div class="big-a">'+shown(saved)+'</div></div></div>':'')+(free<-.1?'<div class="warn">На цілі позначено на '+shown(-free)+' більше, ніж є грошей. Перевірте захист цілей або поверніть частину накопичень у вільні.</div>':'');
  }
  function accountCard(a) {
    return '<div class="acc"><div class="acc-top"><span class="acc-ico" style="background:var(--g'+a.color+')">'+ic(a.type in IC?a.type:'bank')+'</span><span class="acc-n"><b>'+esc(a.name)+'</b><small>'+names[a.type]+'</small></span>'+button(ic('right',18),'account',a.id,'mini-action','aria-label="Відкрити '+esc(a.name)+'"')+'</div><div class="bal-grid">'+Object.entries(a.balances).map(([c,n])=>'<button class="balance-link" data-action="quick" data-id="'+a.id+'" data-currency="'+c+'">'+money(n,c)+'<small>Оновити</small></button>').join('')+'</div><div class="space"><span class="note">'+(a.checked?'Звірено '+dateLabel(a.checked):'Ще не звіряли')+'</span><span class="note">≈ '+shown(E.value(a.balances,store.rates))+'</span></div></div>';
  }
  function goalCard(g) {
    if (!E.live(g)) { const purchase=p.history.find(e=>!e.void&&e.type==='purchase'&&e.goalId===g.id); return '<button type="button" class="goal" data-action="goal" data-id="'+g.id+'"><span class="g-top"><span class="g-ico" style="background:var(--t1);color:var(--g1)">'+ic(g.icon)+'</span><span class="g-name"><b>'+esc(g.name)+'</b><small>'+(purchase?'Куплено за '+money(purchase.amount,purchase.currency):'Кошти повернуто у вільні')+'</small></span><span class="badge-v3">Завершено</span></span></button>'; }
    const saved=E.saved(g,store.rates), percent=Math.min(100,Math.floor(saved/g.target*100));
    return '<button type="button" class="goal" data-action="goal" data-id="'+g.id+'"><span class="g-top"><span class="g-ico" style="background:var(--t'+(g.icon==='home'?1:2)+');color:var(--g'+(g.icon==='home'?1:2)+')">'+ic(g.icon)+'</span><span class="g-name"><b>'+esc(g.name)+'</b><small>'+money(Math.round(saved),g.currency)+' з '+money(g.target,g.currency)+'</small></span><span class="g-pct">'+percent+'%</span></span><span class="trk"><div class="bg"></div><div style="width:'+percent+'%;background:var(--accent)"></div></span><span class="g-bot"><span>'+ (g.protected?'🔒 Захищена · ':'')+(g.status==='paused'?'На паузі':g.monthly?money(g.monthly,g.currency)+'/міс.':'Внески вручну')+'</span><span class="when">'+etaText(g)+'</span></span></button>';
  }
  function etaText(g) { const months=E.eta(g,store.rates); if (!E.live(g)) return 'Завершено'; if (months===0) return 'Суму зібрано'; if (months===null) return g.status==='paused'?'На паузі':'Без прогнозу'; const d=new Date(store.date+'T12:00:00'); d.setDate(1); d.setMonth(d.getMonth()+months); return d.toLocaleDateString('uk-UA',{month:'short',year:'numeric'}); }
  function home() {
    const goals=p.goals.filter(E.live), all=p.accounts.filter(a=>!a.archived);
    return header('Мої гроші')+summary()+'<div class="sec"><h2>Де гроші</h2>'+button('Усі рахунки','go','accounts','mini-action')+'</div>'+all.slice(0,3).map(accountCard).join('')+(goals.length?'<div class="sec"><h2>Ваші цілі</h2>'+button('Усі ('+goals.length+')','go','goals','mini-action')+'</div>'+goals.slice(0,2).map(goalCard).join(''):'<p class="note">Цілі необов’язкові. Можна просто стежити за залишками.</p>')+'<p class="note">Підсумок за останніми записаними залишками. Банки не підключені.</p>';
  }
  function accounts() { return header('Рахунки')+'<div class="space"><span class="note">Усього</span>'+curCtl()+'</div><div class="total">'+shown(E.total(p,store.rates))+'</div>'+p.accounts.filter(a=>!a.archived).map(accountCard).join('')+button('+ Додати рахунок','go','account-new','ghost')+(p.accounts.some(a=>a.archived)?'<div class="sec"><h2>Архів</h2></div><div class="list">'+p.accounts.filter(a=>a.archived).map(a=>row(esc(a.name),'Закритий рахунок','Відновити','restore-account',a.id)).join('')+'</div>':''); }
  const eventNames={expense:'Витрата',income:'Дохід','month-total':'Витрати за місяць',balance:'Оновлення залишку',transfer:'Переказ',contribute:'Внесок у ціль',purchase:'Покупка цілі',month:'Зарплата та внески','goal-create':'Нова ціль','goal-settings':'Налаштування цілі','goal-release':'Кошти звільнено','account-create':'Новий рахунок','salary-settings':'Розклад зарплати','account-settings':'Рахунок'};
  function historyRows(list,forGoal) { return list.length?'<div class="list history-list">'+list.slice().reverse().map(e=>{
    let title=esc(e.note||eventNames[e.type])+(e.void?' · скасовано':''), sub=dateLabel(e.date)+(e.month?' · '+monthLabel(e.month):''), right=e.currency&&e.amount!==undefined?money(e.type==='balance'?e.amount:(e.type==='income'?e.amount:-e.amount),e.currency):ic('right',18);
    if(e.type==='balance'&&e.estimatedExpense){title='Витрати за залишком';right='−'+money(e.estimatedExpense,e.currency);sub+=' · залишилось '+money(e.amount,e.currency);}
    if(forGoal){const share=e.cover?.find(r=>r.goal===forGoal);if(share){right=Object.entries(share.amounts).map(([c,n])=>'−'+money(n,c)).join(' + ');sub+=' · частина загальних витрат';}const c=e.contributions?.find(r=>r.goal===forGoal);if(c)right='+'+money(c.amount,c.currency);}
    return row(title,sub,right,'event',e.id);
  }).join('')+'</div>':'<div class="card"><p class="note">Операцій ще немає. Початкові суми — це залишки, а не дохід.</p></div>'; }
  function accountScreen() {
    const a=aBy(params.id); if(!a) return accounts();
    return header(esc(a.name),'accounts')+'<div class="bal-grid">'+Object.entries(a.balances).map(([c,n])=>'<button class="balance-link" data-action="quick" data-id="'+a.id+'" data-currency="'+c+'"><small>'+c+'</small><b>'+money(n,c)+'</b><small>Витратила / Залишилось</small></button>').join('')+'</div><div class="toolbar">'+button('Дохід','income',a.id)+button('Переказ','transfer',a.id)+'</div><div class="toolbar">'+button('Додати валюту','add-currency',a.id,'second compact')+button('Перейменувати','rename-account',a.id,'second compact')+'</div><div class="sec"><h2>Історія</h2><span>Цей рахунок</span></div>'+historyRows(p.history.filter(e=>e.account===a.id||e.to===a.id||(e.type==='month'&&e.salary&&e.salary.account===a.id)))+button('Архівувати рахунок','archive-account',a.id,'second danger')+'<p class="note">Архівація доступна після обнулення залишків. Історія збережеться.</p>';
  }
  function quickScreen() {
    const a=aBy(params.id), c=params.currency, current=a.balances[c]||0;
    const prior=store.events.filter(e=>!e.void&&e.type==='month-total'&&e.account===a.id&&e.currency===c&&e.month===store.date.slice(0,7)).at(-1);
    const mode=quick.mode;
    const details=p.history.filter(e=>!e.void&&(e.type==='expense'||e.type==='purchase'||(e.type==='balance'&&e.estimatedExpense))&&e.account===a.id&&e.currency===c&&e.date.slice(0,7)===store.date.slice(0,7)).reduce((s,e)=>s+(e.type==='balance'?e.estimatedExpense:e.amount),0);
    return header('Оновити гроші','account')+'<p class="note">'+esc(a.name)+' · '+c+' · '+monthLabel(store.date)+'</p><div class="seg">'+button('Витратила','quick-mode','expense','', 'aria-pressed="'+(mode==='expense')+'"')+button('Залишилось','quick-mode','balance','', 'aria-pressed="'+(mode==='balance')+'"')+'</div>'+form('quick',
      '<div class="fld"><label for="q-amount">'+(mode==='balance'?'Зараз на рахунку, '+c:quick.detail?'Сума цієї покупки, '+c:'Усього витратила цього місяця, '+c)+'</label><input class="big-inp" id="q-amount" name="q-amount" inputmode="decimal" autocomplete="off" placeholder="0" value="'+(mode==='balance'?current/100:!quick.detail&&prior?prior.amount/100:'')+'" required></div>'+
      (mode==='expense'?toggle('q-detail','Записати окрему покупку',quick.detail,'Вимкнено — загальна сума за місяць')+(quick.detail?field('q-note','За що (необов’язково)','','text','maxlength="100"'):'<p class="note">Окремо вже записано '+money(details,c)+'. Вони входять у підсумок, а не додаються зверху.</p>'):toggle('q-expense','Різницю записати у витрати',true,'Вимкніть, якщо це дохід, переказ або виправлення') )+
      '<div class="pv" id="quick-preview"><div class="r2"><span>Зараз записано</span><b>'+money(current,c)+'</b></div></div>','Зберегти')+'<p class="note">Переказ між власними рахунками краще записати дією «Переказ», щоб не вважати його витратою.</p>';
  }
  function quickPayload() {
    const n=amount(val('q-amount')), base={account:params.id,currency:params.currency,date:store.date};
    if(quick.mode==='balance') return {...base,type:'balance',amount:n,asExpense:$('q-expense').checked};
    if(quick.detail) return {...base,type:'expense',amount:n,note:val('q-note').trim()||'Покупка'};
    return {...base,type:'month-total',month:store.date.slice(0,7),amount:n};
  }
  function previewQuick() {
    if(!$('quick-preview'))return;
    if(!val('q-amount').trim()) { $('quick-preview').innerHTML='<p class="help">Введіть суму — одразу покажемо, що зміниться.</p>'; return; }
    try { const next=E.append(store,quickPayload()), projected=E.project(next), e=projected.history.at(-1), diff=(aByFrom(projected,params.id).balances[params.currency]||0)-(aBy(params.id).balances[params.currency]||0);
      $('quick-preview').innerHTML='<div class="r2"><span>Залишиться на рахунку</span><b>'+money(aByFrom(projected,params.id).balances[params.currency],params.currency)+'</b></div><div class="r2"><span>'+(diff>0?'Збільшення':'Додатково спишеться')+'</span><b>'+money(Math.abs(diff),params.currency)+'</b></div>'+coverText(e.cover,projected)+'<div class="r2"><span>Вільно після запису</span><b>'+shown(E.free(projected,store.rates))+'</b></div>';
    } catch(e) { $('quick-preview').innerHTML='<p class="help">'+esc(e.message)+'</p>'; }
  }
  const aByFrom=(projected,id)=>projected.accounts.find(a=>a.id===id);
  function coverText(records,projected=p) { return records.map(r=>'<div class="r2"><span>Із цілі «'+esc(projected.goals.find(g=>g.id===r.goal)?.name||r.goal)+'»</span><b>'+Object.entries(r.amounts).map(([c,n])=>money(n,c)).join(' + ')+'</b></div>').join(''); }
  function incomeScreen() { const a=aBy(params.id);return header('Додати дохід','account')+'<p class="note">'+esc(a.name)+'</p>'+form('income',select('i-currency','Валюта',options(Object.keys(a.balances),params.currency||Object.keys(a.balances)[0]))+field('i-amount','Сума','','text','inputmode="decimal" required')+field('i-note','За що (необов’язково)','','text','maxlength="100"')); }
  function transferScreen() {
    const a=aBy(params.id), others=p.accounts.filter(x=>!x.archived&&x.id!==a.id);
    if(!others.length)return header('Переказ','account')+'<div class="info">Спочатку додайте інший рахунок.</div>'+button('Додати рахунок','go','account-new');
    return header('Переказ','account')+'<p class="note">Звідки: '+esc(a.name)+'</p>'+form('transfer',select('x-currency','Валюта відправлення',options(Object.keys(a.balances),Object.keys(a.balances)[0]))+select('x-to','Куди',options(others,others[0].id,x=>x.name))+select('x-to-currency','Валюта отримання',options(currencies,Object.keys(a.balances)[0]))+field('x-amount','Надіслати','','text','inputmode="decimal" required')+field('x-received','Отримаєте (можна змінити)','','text','inputmode="decimal" required')+field('x-fee','Комісія у валюті відправлення',0,'text','inputmode="decimal"')+'<p class="note">У межах своїх рахунків це не витрата. За різних валют отримана сума визначає фактичний курс.</p>','Зберегти переказ');
  }
  function goals() {
    const goals=p.goals.filter(E.live), finished=p.goals.filter(g=>!E.live(g));
    return header('Цілі')+(p.cats.length?button(ic('cat')+' Ваші коти · '+p.cats.length,'go','cats','shelf'):'')+(goals.length?'<div class="card two"><div><div class="pl-n">На цілі</div><div class="big-a">'+shown(E.pool(p,store.rates))+'</div></div><div><div class="pl-n">Вільно</div><div class="big-a">'+shown(E.free(p,store.rates))+'</div></div></div>'+goals.map(goalCard).join(''):'<div class="card empty">'+ic('tabGoal')+'<h2>Мрія може зачекати</h2><p class="help">Усі гроші поки вільні. Створіть ціль, коли захочете щось запланувати.</p></div>')+button('+ Нова ціль','go','goal-new','ghost')+(finished.length?'<div class="sec"><h2>Завершені</h2></div><div class="list">'+finished.map(g=>row(esc(g.name),g.status==='done'?'Покупку записано':'Кошти повернуто у вільні',ic('right',18),'goal',g.id)).join('')+'</div>':'');
  }
  function goalScreen() {
    const g=gBy(params.id);if(!g)return goals();
    const months=E.eta(g,store.rates), saved=E.saved(g,store.rates);
    return header(esc(g.name),'goals')+goalCard(g)+(E.live(g)?'<div class="pv">'+Object.entries(g.holdings).filter(([,n])=>n>0).map(([c,n])=>'<div class="r2"><span>Фактично відкладено · '+c+'</span><b>'+money(n,c)+'</b></div>').join('')+'<div class="r2"><span>Залишилось до суми</span><b>'+money(Math.max(0,Math.round(g.target-saved)),g.currency)+'</b></div><div class="r2"><span>За вашим планом</span><b>'+ (months===null?'Без дати':months===0?'Суму зібрано':months+' міс. · '+etaText(g))+'</b></div></div>':'')+(E.live(g)?'<div class="card">'+toggle('goal-protected','Не використовувати на інші витрати',g.protected,'Захищає накопичення цієї цілі')+toggle('goal-auto','Відкладати щомісяця',g.auto,'Віртуально резервує кошти, рахунки не змінює')+'</div><div class="toolbar">'+button('Внести','contribute',g.id)+button('Редагувати','edit-goal',g.id)+'</div><div class="toolbar">'+button(g.status==='paused'?'Відновити':'Пауза','pause-goal',g.id)+button('Купити','purchase',g.id,'primary')+'</div>'+button('Закрити й повернути у вільні','release-goal',g.id,'second compact'):'<div class="info">'+(g.status==='done'?'Покупку записано. Невитрачений залишок вільний.':'Ціль закрито, гроші залишилися на рахунках.')+'</div>')+'<div class="sec"><h2>Історія цілі</h2></div>'+historyRows(p.history.filter(e=>e.goalId===g.id||e.goal?.id===g.id||e.cover?.some(r=>r.goal===g.id)||e.contributions?.some(r=>r.goal===g.id)),g.id)+'<p class="note">Дата — оцінка за поточним курсом та внеском. Зміна курсу не обмінює ваші гроші.</p>';
  }
  function goalForm() {
    const g=params.id?gBy(params.id):null;
    return header(g?'Редагувати ціль':'Нова ціль',g?'goal':'goals')+form('goal-save',field('g-name','Назва',g?.name||'','text','required maxlength="60"')+select('g-icon','Значок',options(['home','laptop','plane','car','shield','shoes'],g?.icon||'home',x=>({home:'Дім',laptop:'Ноутбук',plane:'Подорож',car:'Авто',shield:'Резерв',shoes:'Покупка'}[x])))+select('g-currency','Валюта ціни',options(currencies,g?.currency||store.currency))+field('g-target','Потрібна сума',g?g.target/100:'','text','inputmode="decimal" required')+field('g-monthly','Плановий внесок на місяць',g?g.monthly/100:0,'text','inputmode="decimal"')+toggle('g-auto','Відкладати автоматично',g?g.auto:true,'Можна вимкнути та вносити вручну')+'<div class="info" id="goal-preview">Введіть суму й внесок — покажемо орієнтовний строк.</div>');
  }
  function contributeScreen() {const g=gBy(params.id);return header('Внести в ціль','goal')+'<p class="note">'+esc(g.name)+' · вільно '+shown(E.free(p,store.rates))+'</p>'+form('contribute',select('c-currency','Валюта ваших грошей',options(currencies,g.currency))+field('c-amount','Внести','','text','inputmode="decimal" required')+'<div class="info">Гроші залишаються на рахунках. Внесок лише позначає їх як відкладені. Більше потрібної суми не резервуємо.</div>');}
  function purchaseScreen() { const g=gBy(params.id), acc=p.accounts.filter(a=>!a.archived);return header('Купити: '+esc(g.name),'goal')+form('purchase',field('b-price','Фактично сплачена сума',g.target/100,'text','inputmode="decimal" required')+select('b-currency','Валюта платежу',options(currencies,g.currency))+select('b-account','Рахунок оплати',options(acc,acc.find(a=>Object.keys(a.balances).includes(g.currency))?.id||acc[0].id,a=>a.name))+'<div class="pv" id="purchase-preview"></div><div class="info">Запишемо одну витрату та завершимо ціль. Невикористані накопичення стануть вільними. Якщо ціна більша за накопичене, решта береться з вільних.</div>','Записати покупку');}
  function eventScreen() {
    const e=p.history.find(x=>x.id===params.id);if(!e)return header('Історія','more');
    const editable=['expense','month-total','balance','income'].includes(e.type), raw=store.events.find(x=>x.id===e.id);
    return header(esc(e.note||eventNames[e.type]),e.account?'account':'more')+'<p class="note">'+dateLabel(e.date)+(e.account?' · '+esc(aBy(e.account)?.name||''):'')+'</p><div class="pv">'+(e.currency&&e.amount!==undefined?'<div class="r2"><span>'+ (e.type==='balance'?'Фактичний залишок':e.type==='month-total'?'Усього за місяць':'Сума')+'</span><b>'+money(e.amount,e.currency)+'</b></div>':'')+(e.estimatedExpense?'<div class="r2"><span>Витрати за залишком</span><b>−'+money(e.estimatedExpense,e.currency)+'</b></div>':'')+(e.effective!==undefined?'<div class="r2"><span>Окремі покупки вже враховано</span><b>'+money(e.detail,e.currency)+'</b></div><div class="r2"><span>Додано до витрат</span><b>'+money(e.effective,e.currency)+'</b></div>':'')+coverText(e.cover||[])+(e.salary?'<div class="r2"><span>Зарплата</span><b>'+money(e.salary.amount,e.salary.currency)+'</b></div>':'')+(e.contributions||[]).map(c=>'<div class="r2"><span>'+esc(gBy(c.goal)?.name||c.goal)+'</span><b>'+money(c.amount,c.currency)+'</b></div>').join('')+'</div>'+(e.void?'<div class="warn">Операцію скасовано. Ефекти перераховано.</div>':'')+(e.superseded?'<div class="info">Пізніший запис замінив цей підсумок. Повторного списання немає.</div>':'')+(editable&&!e.void?form('event-edit',field('e-amount','Виправити суму',e.amount/100,'text','inputmode="decimal" required')+field('e-note','Опис',e.note||'','text','maxlength="100"'),'Зберегти виправлення'):'')+button(e.void?'Відновити операцію':'Скасувати операцію','event-void',e.id,'second '+(!e.void?'danger':''))+'<p class="note">Виправлення перераховує наступні записи та розподіл по цілях. Наступна звірка залишається фактичним залишком. Дію, що створює від’ємний баланс, не збережемо.</p>';
  }
  function forecast() {
    const monthly=p.salary?.auto?p.salary.amount*store.rates[p.salary.currency]:0, planValue=(store.expensePlan||0)*store.rates[store.expensePlanCurrency||store.currency], exp=Math.round(planValue/store.rates[store.currency]), current=E.total(p,store.rates), vals=[0,1,3,6,12].map(m=>current+m*(monthly-planValue));
    const maximum=Math.max(...vals,1), target=current+period*(monthly-planValue);
    return header('Прогноз')+'<div class="seg">'+[1,3,6,12].map(n=>button(n+' міс.','period',n,'','aria-pressed="'+(period===n)+'"')).join('')+'</div><div class="chart"><div class="chart-bars">'+vals.map((n,i)=>'<div class="chart-bar" style="height:'+Math.max(1,n/maximum*100)+'%"><span>'+[0,1,3,6,12][i]+' міс.</span></div>').join('')+'</div></div><div class="pv"><div class="r2"><span>Зараз</span><b>'+shown(current)+'</b></div><div class="r2"><span>Через '+period+' міс.</span><b>'+shown(target)+'</b></div><div class="r2"><span>Плановий дохід на місяць</span><b>'+shown(monthly)+'</b></div></div>'+form('expense-plan',field('f-plan','Планові витрати на місяць, '+store.currency,exp/100,'text','inputmode="decimal"'),'Оновити прогноз')+'<p class="note">Оцінка за незмінних курсів та плану. Внески в цілі не зменшують загальну суму. Покупки цілей не прогнозуються автоматично, поки ви їх не запишете.</p>';
  }
  function salaryScreen() { const s=p.salary||{account:p.accounts[0].id,currency:'USD',amount:0,day:5,auto:false};return header('Зарплата','more')+form('salary',select('s-account','Куди надходить',options(p.accounts.filter(a=>!a.archived),s.account,a=>a.name))+select('s-currency','Валюта',options(currencies,s.currency))+field('s-amount','Сума на місяць',s.amount/100,'text','inputmode="decimal" required')+field('s-day','Число місяця',s.day,'number','min="1" max="28" required')+toggle('s-auto','Зараховувати автоматично',s.auto,'Для прототипу — один раз за кожен демо-місяць')+'<p class="note">Зміни діють на наступні нарахування. Демо не перевіряє фактичне надходження в банку.</p>');}
  function accountForm() {return header('Новий рахунок','accounts')+form('account-create',field('a-name','Назва','','text','required maxlength="60"')+select('a-type','Тип',options(types,'bank',t=>names[t]))+select('a-currency','Перша валюта',options(currencies,store.currency))+field('a-amount','Зараз є',0,'text','inputmode="decimal" required'));}
  function more() {return header('Ще')+'<div class="card space"><div><div class="pl-n">Дата демо</div><b>'+dateLabel(store.date)+'</b></div><span class="badge-v3">Окрема версія v3</span></div><div class="list">'+row('Зарплата',p.salary?money(p.salary.amount,p.salary.currency)+' щомісяця':'Не налаштовано',ic('right',18),'go','salary')+row('Курси валют','Ручні, лише для підсумків',ic('right',18),'go','rates')+row('Уся історія',p.history.length+' записів',ic('right',18),'go','history')+row('Колекція котів',p.cats.length?'Нові друзі за ваші дії':'З’являться за внески й завершені цілі',ic('right',18),'go','cats')+'</div><div class="sec"><h2>Спробувати місяць</h2></div>'+button('Нарахувати цей місяць','process-month','','primary')+button('Перейти до наступного місяця','next-month')+'<p class="note">Зарплата та внески виконуються один раз на місяць. Повторне натискання не дублює гроші.</p><div class="sec"><h2>Вигляд</h2></div><div class="chips">'+[['a','Синій'],['b','Ніч'],['c','Графіт']].map(([id,n])=>button(n,'look',id,'pill','aria-pressed="'+(store.look===id)+'"')).join('')+'</div><div class="card">'+toggle('calm-mode','Без руху',store.calm)+'</div><div class="sec"><h2>Демо-сценарії</h2></div><div class="demo-grid">'+button('Почати заново','reset','standard','second compact')+button('Без цілей','reset','no-goals','second compact')+button('Нестача коштів','reset','shortage','second compact')+button('Ноутбук за $500','reset','laptop','second compact')+'</div><p class="note">Сценарії замінюють лише дані цього прототипу. Попередній прототип і справжній застосунок не змінюються.</p><a class="note" href="prototype-v2.html">Відкрити попередній прототип v2 ↗</a>';}
  function ratesScreen() { return header('Курси валют','more')+form('rates', '<div class="info">1 одиниця валюти = стільки гривень. Курси в демо вигадані; запитів до банків немає.</div>'+Object.entries(store.rates).filter(([c])=>c!=='UAH').map(([c,r])=>field('rate-'+c,c+' → UAH',r,'number','min="0.000001" step="any" required')).join('')); }
  function cats() {return header('Ваші коти','goals')+(p.cats.length?'<div class="cat-grid">'+p.cats.map(id=>'<div class="cat-card cat-unlock">'+catSvg(id)+'<b>'+esc(CATS[id].n)+'</b><p>'+esc(id==='first'?'За першу завершену покупку цілі.':'За перший внесок у ціль.')+'</p></div>').join('')+'</div>':'<div class="card empty">'+ic('cat',44)+'<h2>Тут оселяться ваші друзі</h2><p class="help">Вони з’являтимуться, поки ви користуєтеся цілями. Облік грошей працює й без колекції.</p></div>');}
  function render() {
    p=E.project(store); document.body.dataset.look=store.look; document.body.classList.toggle('calm',store.calm);
    const screens={home,accounts,account:accountScreen,quick:quickScreen,income:incomeScreen,transfer:transferScreen,goals,goal:goalScreen,'goal-new':goalForm,contribute:contributeScreen,purchase:purchaseScreen,event:eventScreen,forecast,more,salary:salaryScreen,'account-new':accountForm,rates:ratesScreen,cats,history:()=>header('Історія','more')+historyRows(p.history)};
    let html=(screens[route]||home)();
    if(overlay)html+=overlay;
    $('view').innerHTML=(toast?'<div class="toast-v3" role="status">'+esc(toast)+'</div>':'')+(storageWarning?'<div class="warn">'+esc(storageWarning)+'</div>':'')+html;
    $('tabs').innerHTML=[['home','Головна','tabHome'],['accounts','Рахунки','tabAcc'],['goals','Цілі','tabGoal'],['forecast','Прогноз','tabFc'],['more','Ще','tabMore']].map(([id,n,icon])=>'<button type="button" class="tab" data-action="go" data-id="'+id+'" '+(lastTab===id?'aria-current="page"':'')+'>'+ic(icon)+'<span>'+n+'</span></button>').join('');
    if(route==='quick')previewQuick();
    if(route==='goal-new')previewGoal();
    if(route==='purchase')previewPurchase();
  }
  function previewPurchase(){try{const g=gBy(params.id), n=amount(val('b-price')), c=val('b-currency'), a=aBy(val('b-account')), v=n*store.rates[c], reserve=E.value(g.holdings,store.rates), useFree=Math.max(0,v-reserve);$('purchase-preview').innerHTML='<div class="r2"><span>Спишеться з рахунку</span><b>'+money(n,c)+'</b></div><div class="r2"><span>На цьому балансі</span><b>'+money(a.balances[c]||0,c)+'</b></div><div class="r2"><span>Із вільних коштів</span><b>'+shown(useFree)+'</b></div><div class="r2"><span>Залишок цілі стане вільним</span><b>'+shown(Math.max(0,reserve-v))+'</b></div>';}catch(_){}}
  function previewGoal() {try {const target=amount(val('g-target')), m=amount(val('g-monthly')), g=params.id?gBy(params.id):null, cur=val('g-currency'), saved=g?E.value(g.holdings,store.rates)/store.rates[cur]:0;const months=m?Math.max(0,Math.ceil((target-saved)/m)):null; $('goal-preview').textContent=months===null?'Без регулярного внеску: відкладайте вручну, коли зручно.':months===0?'Потрібну суму вже зібрано.':'Орієнтовно '+months+' міс. за внеску '+money(m,cur)+' щомісяця.';}catch(_){}}
  function fail(e) { const target=$('form-error'); if(target)target.textContent=e.message;else {toast=e.message;render();} }
  function processMonth(month) { if(p.months.includes(month)) {toast='Цей місяць уже нарахований. Повторного зарахування немає.'; return;}commit({type:'month',month,date:month+'-'+String(p.salary?.day||5).padStart(2,'0')},'Зарплату та внески за '+monthLabel(month)+' враховано.');}
  document.addEventListener('click',function(ev){const b=ev.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;try{
    if(act==='go') { if(id==='account'&&!params.account&&!params.id)return go('accounts');if(id==='account'){const e=p.history.find(e=>e.id===params.id);return go('account',{id:e?.account||params.id});} if(id==='goal')return go('goal',{id:params.id});return go(id); }
    if(act==='account')return go('account',{id});
    if(act==='quick'){quick={mode:'expense',detail:false};return go('quick',{id,currency:b.dataset.currency});}
    if(act==='quick-mode'){quick.mode=id;render();return;}
    if(act==='goal')return go('goal',{id});
    if(act==='income'||act==='transfer')return go(act,{id});
    if(act==='edit-goal')return go('goal-new',{id});
    if(act==='contribute'||act==='purchase')return go(act,{id});
    if(act==='event')return go('event',{id});
    if(act==='event-void'){const e=store.events.find(e=>e.id===id);persist(E.edit(store,id,{void:!e.void}));toast=e.void?'Операцію відновлено.':'Операцію скасовано. Пов’язані суми перераховано.';}
    else if(act==='pause-goal'){const g=gBy(id);commit({type:'goal-settings',goalId:id,changes:{status:g.status==='paused'?'active':'paused'}},g.status==='paused'?'Внески відновлено.':'Внески на паузі. Накопичення збережено.');}
    else if(act==='release-goal'){commit({type:'goal-release',goalId:id},'Ціль закрито. Гроші залишились на рахунках і стали вільними.');return goWithToast('goals');}
    else if(act==='archive-account'){commit({type:'account-settings',account:id,changes:{archived:true}},'Рахунок в архіві.');return goWithToast('accounts');}
    else if(act==='restore-account'){commit({type:'account-settings',account:id,changes:{archived:false}},'Рахунок відновлено.');}
    else if(act==='rename-account'){const a=aBy(id);overlay=form('rename',field('rename-name','Назва рахунку',a.name,'text','required maxlength="60"'),'Перейменувати');}
    else if(act==='add-currency'){overlay=form('add-currency',select('add-currency','Валюта',options(currencies.filter(c=>!(c in aBy(id).balances)),''))+field('add-amount','Зараз є',0,'text','inputmode="decimal"'),'Додати валюту');}
    else if(act==='look'){persist({...store,look:id});}
    else if(act==='period'){period=Number(id);}
    else if(act==='process-month'){processMonth(store.date.slice(0,7));}
    else if(act==='next-month'){persist({...store,date:E.nextMonth(store.date)});p=E.project(store);processMonth(store.date.slice(0,7));}
    else if(act==='reset'){let n=E.seed(id==='no-goals',today());if(id==='shortage'){n.base.accounts=[{id:'wise',name:'Демо · картка',type:'bank',color:1,balances:{USD:1000000},checked:n.date}];n.base.goals=[{id:'home',name:'Квартира',icon:'home',currency:'USD',target:26000000,monthly:100000,holdings:{USD:900000},auto:true,protected:false,status:'active'},{id:'laptop',name:'Ноутбук',icon:'laptop',currency:'USD',target:200000,monthly:10000,holdings:{USD:100000},auto:true,protected:false,status:'active'}];}if(id==='laptop'){n.base.goals=[{id:'laptop',name:'Ноутбук',icon:'laptop',currency:'USD',target:50000,monthly:16667,holdings:{USD:50000},auto:true,protected:false,status:'active'}];}persist(n);overlay=null;route='home';params={};lastTab='home';toast='Демо готове. Усі суми вигадані.';}
    else return;
    render();
  }catch(e){fail(e);}});
  function goWithToast(next, data={}) {const message=toast;go(next,data);toast=message;render();}
  document.addEventListener('submit',function(ev){const f=ev.target.closest('[data-form]');if(!f)return;ev.preventDefault();try{const type=f.dataset.form;
    if(type==='quick'){const payload=quickPayload();commit(payload,'Гроші оновлено.');const result=E.project(store).history.at(-1);if(result.cover.length)toast+=' Частину покрито з цілей, строки перераховано.';return goWithToast('account',{id:params.id});}
    if(type==='income'){commit({type:'income',account:params.id,currency:val('i-currency'),amount:amount(val('i-amount')),note:val('i-note').trim()||'Дохід'},'Дохід записано.');return goWithToast('account',{id:params.id});}
    if(type==='transfer'){commit({type:'transfer',account:params.id,to:val('x-to'),currency:val('x-currency'),toCurrency:val('x-to-currency'),amount:amount(val('x-amount')),received:amount(val('x-received')),fee:amount(val('x-fee')),note:'Переказ між своїми рахунками'},'Переказ записано один раз, на обох рахунках.');return goWithToast('account',{id:params.id});}
    if(type==='goal-save'){const changes={name:val('g-name').trim(),icon:val('g-icon'),currency:val('g-currency'),target:amount(val('g-target')),monthly:amount(val('g-monthly')),auto:$('g-auto').checked};if(!changes.name||!changes.target)throw new Error('Вкажіть назву й додатну суму цілі.');const id=params.id||'g'+(store.sequence+1);if(params.id)commit({type:'goal-settings',goalId:id,changes},'Ціль оновлено.');else commit({type:'goal-create',goal:{id,...changes,holdings:{},protected:false,status:'active'}},'Ціль створено. Гроші поки не зарезервовані.');return goWithToast('goal',{id});}
    if(type==='contribute'){commit({type:'contribute',goalId:params.id,currency:val('c-currency'),amount:amount(val('c-amount'))},'Внесок збережено. Рахунки не змінились.');return goWithToast('goal',{id:params.id});}
    if(type==='purchase'){commit({type:'purchase',goalId:params.id,account:val('b-account'),currency:val('b-currency'),amount:amount(val('b-price')),note:'Покупка: '+gBy(params.id).name},'Покупку записано. Решта накопичень вільна.');return goWithToast('goal',{id:params.id});}
    if(type==='event-edit'){persist(E.edit(store,params.id,{amount:amount(val('e-amount')),note:val('e-note').trim()}));toast='Виправлено. Залишки, цілі та строки перераховано.';return render();}
    if(type==='salary'){const n=amount(val('s-amount'));if(!n)throw new Error('Вкажіть додатну суму зарплати.');commit({type:'salary-settings',salary:{account:val('s-account'),currency:val('s-currency'),amount:n,day:Number(val('s-day')),auto:$('s-auto').checked}},'План зарплати збережено.');return goWithToast('more');}
    if(type==='expense-plan'){persist({...store,expensePlan:amount(val('f-plan')),expensePlanCurrency:store.currency});toast='Прогноз оновлено. Фактичні гроші не змінились.';return render();}
    if(type==='account-create'){const name=val('a-name').trim();if(!name)throw new Error('Вкажіть назву рахунку.');const id='a'+(store.sequence+1);commit({type:'account-create',accountData:{id,name,type:val('a-type'),color:(store.sequence%4)+1,balances:{[val('a-currency')]:amount(val('a-amount'))},checked:store.date}},'Рахунок додано. Це початковий залишок, не дохід.');return goWithToast('account',{id});}
    if(type==='rates'){const rates={UAH:1};for(const c of currencies.filter(c=>c!=='UAH')){const r=Number(val('rate-'+c));if(!Number.isFinite(r)||r<=0||r>1e8)throw new Error('Курс має бути додатним числом.');rates[c]=r;}persist({...store,rates});toast='Курси оновлено. Оригінальні суми не змінились.';return render();}
    if(type==='rename'){const name=val('rename-name').trim();if(!name)throw new Error('Вкажіть назву.');commit({type:'account-settings',account:params.id,changes:{name}},'Назву змінено.');overlay=null;return render();}
    if(type==='add-currency'){const c=val('add-currency');if(!c)throw new Error('Усі валюти вже додано.');commit({type:'balance',account:params.id,currency:c,amount:amount(val('add-amount')),asExpense:false},'Валюту додано.');overlay=null;return render();}
  }catch(e){fail(e);}});
  document.addEventListener('input',function(ev){if(route==='quick'&&['q-amount','q-expense'].includes(ev.target.id))previewQuick();if(route==='goal-new')previewGoal();if(route==='purchase')previewPurchase();if(route==='transfer'&&['x-amount','x-currency','x-to-currency'].includes(ev.target.id)){try{$('x-received').value=Math.round(amount(val('x-amount'))*store.rates[val('x-currency')]/store.rates[val('x-to-currency')])/100;}catch(_){}}});
  document.addEventListener('change',function(ev){const id=ev.target.id;try{
    if(id==='show-currency'){persist({...store,currency:ev.target.value});return render();}
    if(id==='q-detail'){quick.detail=ev.target.checked;return render();}
    if(id==='q-expense')return previewQuick();
    if(id==='goal-protected'||id==='goal-auto'){commit({type:'goal-settings',goalId:params.id,changes:{[id==='goal-protected'?'protected':'auto']:ev.target.checked}},'Налаштування збережено.');return render();}
    if(id==='calm-mode'){persist({...store,calm:ev.target.checked});return render();}
    if(route==='goal-new')previewGoal();
    if(route==='purchase')previewPurchase();
  }catch(e){fail(e);}});
  render();
})();
